let calendarData={series:[],nextCursor:null},calendarGeneration=0,calendarPreview=null,calendarBusy=false;
const calendarPolicyCopy='夏令时不存在的时间跳过；重复时间只选一次。错过但尚未提交的日期跳过；已提交的原生提醒可能晚到。恢复时跳过逾期暂停项；暂停或取消不能撤回已派发工作。每次触发使用届时配置的模型，可能产生供应商费用。';
function calendarStorageKey(){return 'opendots:calendar-attempt:'+String(state.binding?.sessionId||'unbound');}
function readCalendarAttempt(){try{return JSON.parse(sessionStorage.getItem(calendarStorageKey())||'null')}catch{return null;}}
function saveCalendarAttempt(value){if(value)sessionStorage.setItem(calendarStorageKey(),JSON.stringify(value));else sessionStorage.removeItem(calendarStorageKey());}
function calendarPanel(){return `${proposalPanel()}<div class="section-head section-space"><h3>按本地日历重复</h3><button data-calendar="refresh">刷新清单</button></div><div id="calendar-list"><p class="small muted">正在读取日历提醒…</p></div><details class="panel panel-pad"><summary>＋ 每天 / 每周提醒</summary><form id="calendar-form"><label class="form-field">提醒内容<input name="intent" required maxlength="2000"></label><label class="form-field">频率<select name="frequency"><option value="daily">每天</option><option value="weekly">每周</option></select></label><label class="form-field">本地时间<input name="localTime" type="time" required></label><label class="form-field">IANA 时区<input name="timeZone" required value="${escapeHtml(Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC')}"></label><label class="form-field">开始日期<input name="startDate" type="date" required></label><label class="form-field">结束日期（含，可选）<input name="untilDate" type="date"></label><fieldset><legend class="small">每周的星期（仅“每周”生效）</legend>${['一','二','三','四','五','六','日'].map((label,i)=>`<label class="small"><input type="checkbox" name="weekdays" value="${i+1}">周${label} </label>`).join('')}</fieldset><label class="form-field">夏令时重复时间<select name="overlap"><option value="earlier">较早的一次</option><option value="later">较晚的一次</option></select></label><p class="small muted">${calendarPolicyCopy}</p><button class="primary">计算并核对 UTC 预览</button></form></details><div class="actions"><button data-calendar="reconcile">核对已确认的重复计划</button></div><p class="small muted">核对会继续落实已确认计划，不新建规则。清单刷新只读，不自动预览或派发。</p>`;}
function calendarTimes(items){return items.map(t=>`<li><strong>${escapeHtml(t.localDate)} ${escapeHtml(t.localTime)}</strong> · ${escapeHtml(t.timeZone)}<br>UTC：${escapeHtml(t.instant)} · 偏移 ${escapeHtml(t.offset)}${t.ambiguous?' · 重复时刻采用'+(t.overlap==='later'?'较晚':'较早')+'一次':''}</li>`).join('');}
function calendarControlButtons(s){if(s.recoveryDecisionRequired===true){const actions=s.desiredState==='cancelled'?['cancel']:['pause','resume','cancel'];return `<p class="runtime-note">检测到已确认的外部控制变更。当前原生状态：${escapeHtml(statusName(s.occurrence?.schedule?.status))}。请按当前计划版本 ${escapeHtml(s.revision)} 重新决定；不会自动覆盖外部操作。</p>${actions.map(action=>`<button data-calendar-id="${escapeHtml(s.id)}" data-calendar-control="${action}">重新确认${action==='pause'?'暂停':action==='resume'?'恢复':'取消'}</button>`).join('')}`;}if(s.desiredState==='cancelled'||s.ended)return '';return `<button data-calendar-id="${escapeHtml(s.id)}" data-calendar-control="${s.desiredState==='paused'?'resume':'pause'}" ${s.controlPending?'disabled':''}>${s.desiredState==='paused'?'恢复':'暂停'}</button><button data-calendar-id="${escapeHtml(s.id)}" data-calendar-control="cancel" ${s.controlPending?'disabled':''}>取消计划</button>`;}
function renderCalendars(){if(authEnded||view!=='tasks'||!$('calendar-list'))return;const attempt=readCalendarAttempt();$('calendar-list').innerHTML=(attempt?'<div class="runtime-note">有一项日历提醒提交尚未确认。刷新后仍保留原编号，不会自动新建。<button data-calendar="recover">核对原请求</button></div>':'')+(calendarData.series.length?calendarData.series.map(s=>`<article class="panel panel-pad"><div class="section-head"><strong>${escapeHtml(s.rule.intent)}</strong><span class="tag">${escapeHtml(s.ended?'已结束':s.controlPending?'控制待核查':('期望状态：'+statusName(s.desiredState)))}</span></div><p class="small muted">${s.rule.frequency==='weekly'?'每周 '+escapeHtml((s.rule.weekdays||[]).join('、')):'每天'} · ${escapeHtml(s.rule.localTime)} · ${escapeHtml(s.rule.timeZone)}</p>${s.occurrence?`<ul class="small">${calendarTimes([s.occurrence.time])}</ul><p class="small muted">本次：${escapeHtml(s.occurrence.state)} · 原生状态 ${escapeHtml(statusName(s.occurrence.schedule?.status||'尚未确认'))}</p>`:'<p class="small muted">尚无已登记的下一次触发时刻。</p>'}${s.errorCode?'<p class="inline-error">'+escapeHtml(s.errorCode)+'</p>':''}<div class="actions"><button data-calendar-history="${escapeHtml(s.id)}">查看触发记录</button>${calendarControlButtons(s)}</div></article>`).join(''):empty('没有按日历重复的提醒','每天 / 每周会按照明确的本地时间、时区和夏令时策略计算。'))+(calendarData.nextCursor?'<button data-calendar="more">加载更多计划</button>':'');}
async function loadCalendars(more=false){const generation=++calendarGeneration,identity=connectorSessionIdentity();try{const result=more?await request('/api/calendar-reminders/page','POST',{afterId:calendarData.nextCursor,limit:25}):await request('/api/calendar-reminders');if(authEnded||generation!==calendarGeneration||identity!==connectorSessionIdentity())return;calendarData={series:more?[...calendarData.series,...result.series]:result.series||[],nextCursor:result.nextCursor||null};renderCalendars();}catch(error){if(!authEnded&&generation===calendarGeneration&&view==='tasks')$('calendar-list').textContent=error.message;}}
function parseCalendarRule(form){const fields=new FormData(form),frequency=String(fields.get('frequency'));const rule={intent:String(fields.get('intent')||'').trim(),timeZone:String(fields.get('timeZone')||''),frequency,localTime:String(fields.get('localTime')||''),startDate:String(fields.get('startDate')||''),dst:{gap:'skip',overlap:String(fields.get('overlap'))},missed:'skip_unsubmitted',resume:'skip_overdue_paused'};const until=String(fields.get('untilDate')||'');if(until)rule.untilDate=until;if(frequency==='weekly')rule.weekdays=[...new Set(fields.getAll('weekdays').map(Number))].sort((a,b)=>a-b);return rule;}
async function previewCalendar(form){if(calendarBusy||authEnded)return;const prior=readCalendarAttempt();if(prior&&calendarRecoveryKey!==prior.key){toast('请先核对原请求结果，再创建新的日历计划。');return;}const generation=++modalGeneration,identity=connectorSessionIdentity();calendarBusy=true;try{const data=await request('/api/calendar-reminders/preview','POST',{rule:parseCalendarRule(form)});if(authEnded||generation!==modalGeneration||identity!==connectorSessionIdentity())return;openModal(`<h2>核对日历提醒</h2><p>${escapeHtml(data.rule.intent)}</p><p class="small muted">${data.rule.frequency==='weekly'?'每周 '+escapeHtml((data.rule.weekdays||[]).join('、')):'每天'} · ${escapeHtml(data.rule.localTime)} · ${escapeHtml(data.rule.timeZone)}<br>日期范围：${escapeHtml(data.rule.startDate)} 至 ${escapeHtml(data.rule.untilDate||'未设置结束日期')}<br>重复时间选择：${data.rule.dst?.overlap==='later'?'较晚一次':'较早一次'}</p><ul class="small">${calendarTimes(data.occurrences||[])}</ul><p class="small muted">夏令时空缺跳过：${escapeHtml(data.skippedGaps)} · ${data.exhausted?'搜索范围已耗尽':'按当前计算版本预览'}<br>${escapeHtml(data.calculationVersion)}</p><p>${calendarPolicyCopy}</p><p id="calendar-feedback" class="inline-error" role="status"></p><div class="modal-actions"><button data-action="close-modal">返回修改</button><button data-calendar="confirm" ${!data.occurrences?.length?'disabled':''}>确认这些时间并创建</button></div>`,{expectedGeneration:generation});calendarPreview={...JSON.parse(JSON.stringify(data)),generation:modalGeneration,identity,key:prior?.key||crypto.randomUUID(),sent:false};}catch(error){if(generation===modalGeneration)toast(error.message)}finally{calendarBusy=false;}}
async function submitCalendar(){const v=calendarPreview;if(!v||v.generation!==modalGeneration||calendarBusy||authEnded)return;if(v.identity!==connectorSessionIdentity()){closeModal();toast('登录会话已变化，请重新预览并确认。');return;}const identity=v.identity;calendarBusy=true;try{saveCalendarAttempt({kind:'create',key:v.key,previewFingerprint:v.previewFingerprint});v.sent=true;await request('/api/calendar-reminders','POST',{rule:v.rule,idempotencyKey:v.key,confirmed:true,...(v.previewFingerprint?{previewFingerprint:v.previewFingerprint}:{})});if(authEnded||identity!==connectorSessionIdentity())return;saveCalendarAttempt(null);calendarRecoveryKey=null;calendarPreview=null;if(v.generation===modalGeneration)closeModal();toast('重复计划已登记；实际执行以原生调度状态为准。');await loadCalendars();}catch(error){if(authEnded||identity!==connectorSessionIdentity())return;if(error.code==='calendar_preview_changed'||error.message==='calendar_preview_changed'){calendarRecoveryKey=v.key;calendarPreview=null;if(v.generation===modalGeneration){closeModal();toast('预览已变化。请重新核对 UTC 预览，将沿用原请求编号。');}}else if(v.generation===modalGeneration)$('calendar-feedback').textContent='提交未确认：'+error.message+'。保留原请求编号；不要另建相同计划。';}finally{calendarBusy=false;}}
async function calendarHistory(id){const generation=++modalGeneration,identity=connectorSessionIdentity();try{const result=await request('/api/calendar-reminders/'+encodeURIComponent(id)+'/occurrences');if(authEnded||generation!==modalGeneration||identity!==connectorSessionIdentity())return;openModal(`<h2>已登记的触发记录</h2>${(result.occurrences||[]).map(o=>`<ul class="small">${calendarTimes([o.time])}</ul><p class="small muted">${escapeHtml(o.state)} · ${escapeHtml(statusName(o.schedule?.status||'未确认'))} ${escapeHtml(o.errorCode||'')}</p>`).join('')||'<p>尚无触发记录。</p>'}<p class="small muted">已派发工作由原生调度器管理，取消计划不能撤回它。</p><button data-action="close-modal">关闭</button>`,{expectedGeneration:generation});}catch(error){if(generation===modalGeneration)toast(error.message);}}
async function findCalendarAttempt(attempt){let after=null;const seen=new Set();do{const result=after?await request('/api/calendar-reminders/page','POST',{afterId:after,limit:50}):await request('/api/calendar-reminders');const match=(result.series||[]).find(s=>attempt.kind==='create'?s.createCommand?.idempotencyKey===attempt.key:s.id===attempt.id);if(match)return match;after=result.nextCursor;if(after&&seen.has(after))throw new Error('计划分页游标重复，请稍后重试');seen.add(after);}while(after);return null;}
async function recoverCalendar(){const attempt=readCalendarAttempt();if(!attempt||calendarBusy||authEnded)return;calendarBusy=true;const generation=++modalGeneration,identity=connectorSessionIdentity();try{const series=await findCalendarAttempt(attempt);if(authEnded||generation!==modalGeneration||identity!==connectorSessionIdentity())return;if(attempt.kind==='control'){openCalendarControl({id:attempt.id,rule:series?.rule||{intent:'原计划'},revision:attempt.expectedRevision},attempt.action,attempt);return;}if(series){openModal(`<h2>核对原计划提交</h2><p>${escapeHtml(series.rule.intent)}</p><div class="code-display">${safeJson(series.rule)}</div>${series.occurrence?'<ul class="small">'+calendarTimes([series.occurrence.time])+'</ul>':''}<p>服务端已有此编号的计划。继续只重试原请求，不创建另一个计划。</p><p class="small muted">${calendarPolicyCopy}</p><p id="calendar-feedback" class="inline-error"></p><button data-calendar="confirm">核对同一计划回执</button><button data-action="close-modal">关闭</button>`,{expectedGeneration:generation});calendarPreview={rule:JSON.parse(JSON.stringify(series.rule)),key:attempt.key,generation:modalGeneration,identity,sent:true};}else{calendarRecoveryKey=attempt.key;toast('尚未找到服务端回执。请重新填写完全相同的规则并预览；将沿用原编号，不会另建编号。');}}catch(error){if(generation===modalGeneration)toast(error.message)}finally{calendarBusy=false;}}
let calendarRecoveryKey=null;
function openCalendarControl(series,action,attempt=null){const snapshot=JSON.parse(JSON.stringify(series));const key=attempt?.key||crypto.randomUUID(),identity=connectorSessionIdentity();openModal(`<h2>${action==='pause'?'暂停':action==='resume'?'恢复':'取消'}这项日历计划</h2><p>${escapeHtml(snapshot.rule.intent)}</p><p>计划版本：${escapeHtml(snapshot.revision)}。${snapshot.recoveryDecisionRequired?'已确认的原生状态：'+escapeHtml(statusName(snapshot.occurrence?.schedule?.status))+'；这是针对外部控制变化的新决定。':''}${calendarPolicyCopy}</p><p id="calendar-control-feedback" class="inline-error" role="status"></p><div class="modal-actions"><button data-action="close-modal">返回</button><button id="calendar-control-confirm">确认这一次${attempt?'原请求重试':''}</button></div>`);const generation=modalGeneration;const button=$('calendar-control-confirm');button.addEventListener('click',async()=>{if(calendarBusy||generation!==modalGeneration||authEnded||button.disabled)return;if(identity!==connectorSessionIdentity()){closeModal();toast('登录会话已变化，请重新核对计划后决定。');return;}button.disabled=true;calendarBusy=true;try{saveCalendarAttempt({kind:'control',key,id:snapshot.id,action,expectedRevision:snapshot.revision});await request('/api/calendar-reminders/'+encodeURIComponent(snapshot.id)+'/control','POST',{action,expectedRevision:snapshot.revision,idempotencyKey:key,confirmed:true});if(authEnded||identity!==connectorSessionIdentity())return;saveCalendarAttempt(null);if(generation===modalGeneration)closeModal();await loadCalendars();toast('已登记控制意图；请查看原生提醒状态。');}catch(error){if((error.code==='calendar_revision_conflict'||error.message==='calendar_revision_conflict')&&identity===connectorSessionIdentity()&&!authEnded){saveCalendarAttempt(null);if(generation===modalGeneration){closeModal();toast('原控制请求因版本过期被拒绝。请刷新计划并重新决定，不会自动套用新版本。');}await loadCalendars();}else if(generation===modalGeneration)$('calendar-control-feedback').textContent='控制未确认：'+error.message+'。保留原编号与版本，请用“核对原请求”继续。';}finally{calendarBusy=false;}});}
function controlCalendar(id,action){if(calendarBusy||authEnded||!['pause','resume','cancel'].includes(action))return;if(readCalendarAttempt()){toast('请先核对原请求。');return;}const series=calendarData.series.find(s=>s.id===id);if(!series||(series.controlPending&&series.recoveryDecisionRequired!==true)||(series.desiredState==='cancelled'&&action!=='cancel'))return;openCalendarControl(series,action);}
async function calendarAction(action){if(action==='refresh')return loadCalendars();if(action==='more')return loadCalendars(true);if(action==='recover')return recoverCalendar();if(action==='confirm')return submitCalendar();if(action==='reconcile'){if(calendarBusy||authEnded)return;if(!window.confirm('核对会继续落实已确认的日历计划，可能登记下一次原生提醒。每次触发使用届时配置的模型，可能收费。继续吗？'))return;calendarBusy=true;try{await request('/api/calendar-reminders/reconcile','POST',{});await loadCalendars();toast('已核对；请查看各计划及原生提醒的实际状态。');}catch(error){toast('核对结果未确认：'+error.message+'；不会自动重试。');}finally{calendarBusy=false;}}}
let remindersData=[];
function remindersPanel(){return `<div class="section-head section-space"><h3>提醒与定时任务</h3><button data-action="refresh-reminders">刷新</button></div><div id="reminders-list"><p class="small muted">正在读取提醒…</p></div><details class="panel panel-pad"><summary>＋ 新建提醒</summary><form id="reminder-form"><label class="form-field">提醒内容<input name="intent" required maxlength="2000"></label><label class="form-field">首次触发时间（必须包含时区偏移）<input name="at" required placeholder="2026-10-01T09:00:00+08:00"></label><label class="form-field">IANA 时区<input name="timeZone" required value="${escapeHtml(Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC')}"></label><label class="form-field">重复间隔（秒，可选，至少 60）<input name="intervalSeconds" type="number" min="60" step="1"></label><p class="small muted">这是固定秒数间隔，不是按本地日历或夏令时自动调整的“每天”。提交前会显示确定的 UTC 时刻。</p><button class="primary">核对并创建提醒</button></form></details>`}
async function loadReminders(){try{const data=await request('/api/reminders');remindersData=data.reminders||[];if(view!=='tasks'||!$('reminders-list'))return;$('reminders-list').innerHTML=remindersData.length?remindersData.map(r=>`<div class="panel panel-pad"><div class="section-head"><strong class="small">${escapeHtml(r.input?.intent||r.schedule?.intent||'提醒')}</strong><span class="tag">${escapeHtml(r.state==='confirmed'?statusName(r.schedule?.status):r.state==='unknown'?'结果待核查':'提交中')}</span></div><p class="small muted">${escapeHtml(r.input?.at)} · ${escapeHtml(r.input?.timeZone)}${r.input?.intervalSeconds?' · 每 '+escapeHtml(r.input.intervalSeconds)+' 秒':''}</p>${r.error?'<p class="inline-error">'+escapeHtml(r.error)+'</p>':''}${r.state==='confirmed'&&r.schedule&&!['completed','cancelled'].includes(r.schedule.status)?`<button data-reminder="${escapeHtml(r.id)}" data-control="${r.schedule.status==='paused'?'resume':'pause'}">${r.schedule.status==='paused'?'恢复':'暂停'}</button> <button data-reminder="${escapeHtml(r.id)}" data-control="cancel">取消</button>`:''}</div>`).join(''):empty('还没有定时提醒','你明确建立的提醒会保留触发时间、时区和状态。')}catch(error){if($('reminders-list'))$('reminders-list').textContent=error.message}}
function parseReminder(form){const values=new FormData(form);const at=String(values.get('at')||'');if(!/T\d{2}:\d{2}(:\d{2}(\.\d+)?)?(Z|[+-]\d{2}:\d{2})$/.test(at)||Number.isNaN(Date.parse(at)))throw new Error('请输入包含明确时区偏移的 RFC3339 时间');const timeZone=String(values.get('timeZone')||'');try{new Intl.DateTimeFormat('en',{timeZone})}catch{throw new Error('请输入有效的 IANA 时区')}const interval=String(values.get('intervalSeconds')||'');if(interval&&(!Number.isInteger(Number(interval))||Number(interval)<60))throw new Error('重复间隔至少为 60 秒整数');return {intent:String(values.get('intent')||''),at,timeZone,...(interval?{intervalSeconds:Number(interval)}:{})};}
async function createReminder(form){if(busy)return;try{const input=parseReminder(form);if(!window.confirm('确认创建提醒：'+input.intent+'\nUTC 时刻：'+new Date(input.at).toISOString()+'\n标记时区：'+input.timeZone+(input.intervalSeconds?'\n固定间隔：'+input.intervalSeconds+' 秒':'\n仅一次')))return;const prior=remindersData.find(r=>r.state!=='confirmed'&&r.input?.intent===input.intent&&r.input?.at===input.at&&r.input?.timeZone===input.timeZone&&r.input?.intervalSeconds===input.intervalSeconds);busy=true;await request('/api/reminders','POST',{...input,idempotencyKey:prior?.input?.idempotencyKey||crypto.randomUUID()});form.reset();toast('提醒请求已提交，结果以调度器状态为准');await loadReminders()}catch(error){toast(error.message)}finally{busy=false}}
async function controlReminder(id,action){const r=remindersData.find(r=>r.id===id);if(!r?.schedule||busy)return;if(action==='cancel'&&!window.confirm('取消这项提醒？已经触发的工作不会因此撤回。'))return;busy=true;try{await request('/api/reminders/'+encodeURIComponent(id)+'/control','POST',{action,expectedRevision:r.schedule.revision});await loadReminders()}catch(error){toast(error.message)}finally{busy=false}}

let ownerSessions=null,ownerSessionsGeneration=0,authEnded=false;
function leaveOwnerSession(){if(authEnded)return;authEnded=true;ownerSessionsGeneration++;connectorGeneration++;connectorInventory=null;connectorNative=null;connectorError='';connectorLoading=false;closeModal();disconnectDesktop();uploadStopRequested=true;uploadController?.abort();attachmentItems.forEach(i=>{i.file=null});attachmentItems=[];attachmentInventory=[];attachmentDraft=null;draft='';pendingSubmission=null;settingsData=null;memoryResult=null;displayedMemory=null;remindersData=[];proposalListGeneration++;proposalData={enabled:false,proposals:[],nextCursor:null};activeProposal=null;artifactLoadGeneration++;documentGeneration++;artifactInventory=[];documentData={documents:[],nextCursor:null};activeDocument=null;artifactEditor=null;calendarGeneration++;calendarData={series:[],nextCursor:null};calendarPreview=null;calendarRecoveryKey=null;notificationView=null;ownerSessions=null;voiceCapability=null;computerData={configured:false,state:null,capabilities:{}};state={runtime:{status:'unavailable',message:'登录已失效'},messages:[],jobs:[],approvals:[],commands:[],threads:[],drafts:[]};lastState='';$('content').innerHTML='<div class="runtime-note">登录已失效，正在转到登录页。</div>';$('modal').innerHTML='';$('connection').textContent='需要登录';$('notification-count').textContent='0';$('toast').textContent='';$('toast').hidden=true;nav();location.replace('/login');}
async function appFetch(path,options){if(authEnded)throw new Error('登录已失效');const response=await fetch(path,options);if(response.status===401){leaveOwnerSession();throw Object.assign(new Error('登录已失效'),{status:401});}if(authEnded)throw new Error('登录已失效');return response;}
async function loadOwnerSessions(){const generation=++ownerSessionsGeneration;try{const auth=await request('/api/auth');if(generation!==ownerSessionsGeneration||authEnded)return;if(!auth.enabled){ownerSessions={enabled:false,devices:[]};renderOwnerSessions();return;}if(!auth.authenticated){leaveOwnerSession();return;}const data=await request('/api/auth/devices');if(generation!==ownerSessionsGeneration||authEnded)return;ownerSessions={enabled:true,devices:JSON.parse(JSON.stringify(data.devices||[]))};renderOwnerSessions();}catch(error){if(generation===ownerSessionsGeneration&&!authEnded&&view==='settings')$('owner-sessions').innerHTML='<p class="inline-error">'+escapeHtml(error.message)+'</p><button data-owner-session="refresh">重新读取</button>';}}
function renderOwnerSessions(){if(view!=='settings'||!$('owner-sessions'))return;const data=ownerSessions;if(!data){$('owner-sessions').innerHTML='<p class="small muted">正在读取登录状态…</p>';return;}if(!data.enabled){$('owner-sessions').innerHTML='<p class="small muted">此部署未启用所有者登录，当前没有设备会话管理。</p>';return;}$('owner-sessions').innerHTML=`<p class="small muted">仅列出你的登录会话。撤销会使对应连接失效；不会停止 Runtime 后台任务。</p>${data.devices.map(device=>`<article class="panel panel-pad"><strong class="small">${escapeHtml(device.deviceLabel||'未命名设备')}</strong> ${device.current?'<span class="tag">当前会话</span>':''}<p class="small muted">创建：${escapeHtml(formatTime(device.createdAt))}<br>最近使用：${escapeHtml(formatTime(device.lastSeenAt))}<br>到期：${escapeHtml(formatTime(device.expiresAt))}</p><button data-owner-device="${escapeHtml(device.id)}">${device.current?'退出当前会话':'撤销此会话'}</button></article>`).join('')||'<p class="small muted">没有可显示的会话。</p>'}<div class="actions"><button data-owner-session="refresh">刷新列表</button><button data-owner-session="logout">退出登录</button><button data-owner-session="all">退出全部会话</button></div><p class="small muted">退出全部包含你正在使用的会话，不是仅退出其他设备。</p>`;}
function openOwnerSessionAction(action,id){if(!ownerSessions?.enabled||authEnded)return;const selected=id?ownerSessions.devices.find(d=>d.id===id):null;if(id&&!selected)return;const snapshot=selected?JSON.parse(JSON.stringify(selected)):null;const kind=snapshot?'revoke':action;const label=kind==='all'?'退出全部会话（包括当前）':kind==='logout'?'退出当前登录':('撤销“'+(snapshot.deviceLabel||'未命名设备')+'”');const html=`<h2>${escapeHtml(label)}</h2><p>此操作会撤销登录访问，不会撤回已发生的操作，也不会停止后台任务。</p>${snapshot?`<div class="code-display">${safeJson({device:snapshot.deviceLabel,sessionId:snapshot.id,createdAt:snapshot.createdAt,lastSeenAt:snapshot.lastSeenAt})}</div>`:''}<p id="owner-session-feedback" class="inline-error" role="status"></p><div class="modal-actions"><button data-action="close-modal">取消</button><button id="owner-session-confirm">确认${kind==='all'?'退出全部':'撤销 / 退出'}</button></div>`;openModal(html);const generation=modalGeneration;const button=$('owner-session-confirm');button.addEventListener('click',async()=>{if(button.disabled||generation!==modalGeneration||authEnded)return;button.disabled=true;try{const path=kind==='all'?'/api/auth/revoke-all':kind==='logout'?'/api/auth/logout':'/api/auth/devices/'+encodeURIComponent(snapshot.id)+'/revoke';const result=await request(path,'POST',{});if(kind==='all'||kind==='logout'||result.current===true){leaveOwnerSession();return;}if(generation===modalGeneration)closeModal();await loadOwnerSessions();toast('已撤销所选会话。');}catch(error){if(generation!==modalGeneration||authEnded)return;$('owner-session-feedback').textContent='结果未确认：'+error.message+'。请关闭并刷新会话列表核对；不会自动重发。';}});}
let connectorInventory=null,connectorNative=null,connectorGeneration=0,connectorLoading=false,connectorError='';
function connectorSessionIdentity(){return JSON.stringify([state.authentication?.session?.id,state.binding?.sessionId]);}
async function loadConnectors(native=false){if(authEnded)return;const generation=++connectorGeneration,identity=connectorSessionIdentity();const current=()=>!authEnded&&generation===connectorGeneration&&identity===connectorSessionIdentity();connectorLoading=true;connectorError='';connectorNative=null;renderConnectors();try{const nativeData=native?await request('/api/connectors/native'):null;if(!current())return;const inventory=await request('/api/connectors');if(!current())return;connectorInventory=inventory;connectorNative=nativeData;}catch(error){if(!current())return;connectorInventory=null;connectorNative=null;connectorError=error.message;}finally{if(current()){connectorLoading=false;renderConnectors();}else if(!authEnded&&generation===connectorGeneration){connectorLoading=false;connectorInventory=null;connectorNative=null;connectorError='登录会话已变化，请重新读取清单';renderConnectors();}}}
function renderConnectors(){if(authEnded||view!=='settings'||!$('connector-inventory'))return;const data=connectorInventory;const labels={disabled:'未启用',configured:'已配置',starting:'正在启动',ready:'回调监听已就绪',unavailable:'暂时不可用',closed:'已关闭'};const registration={unverified:'未核验',advertised:'Runtime 已声明',missing:'未找到声明'};const connectors=data?.catalogue?.connectors||data?.connectors||[];$('connector-inventory').innerHTML=`<p class="small muted">这里只查看部署配置，不会自动访问 GitHub。公开仓库读取不代表你已连接 GitHub 账户。</p>${connectorLoading?'<p class="small muted" role="status">正在读取声明状态…</p>':''}${connectorError?'<p class="inline-error" role="alert">'+escapeHtml(connectorError)+'。当前状态未确认，不沿用旧清单。</p>':''}${data?`<span class="tag">${escapeHtml(labels[data.status]||data.status||'未知')}</span><p class="small muted">${escapeHtml(data.message||'')}</p>${data.status==='disabled'?'<p class="small muted">此部署没有启用连接器。</p>':`<p class="small muted">访问范围：公开数据 · 账户连接：无<br>回调监听：${data.callbackListening?'已监听（不证明外部服务可用）':'未监听 / 未确认'}<br>原生注册：${escapeHtml(registration[data.nativeRegistration]||'未核验')}</p>${connectors.map(c=>`<article class="panel panel-pad"><strong>${escapeHtml(c.label||c.id)}</strong><p class="small muted">操作仅限 public_read；仓库范围由部署者固定配置。</p><h4 class="small">允许的公开仓库</h4><div class="code-display">${safeJson(c.status?.repositories||[])}</div><h4 class="small">已登记的只读操作</h4>${(c.operations||[]).map(operation=>`<details><summary class="small">${escapeHtml(operation.id)} · ${escapeHtml(operation.effect)}</summary><p class="small muted">${escapeHtml(operation.description||'')}</p><div class="code-display">${safeJson(operation.inputSchema||{})}</div></details>`).join('')||'<p class="small muted">未列出操作。</p>'}<p class="small muted">最近成功读取：${c.status?.lastSuccessfulReadAt?escapeHtml(formatTime(c.status.lastSuccessfulReadAt)):'尚无记录'}。该记录不证明当前连接可用。</p></article>`).join('')}`}`:''}<div class="actions"><button data-connectors="config" ${connectorLoading?'disabled':''}>刷新配置清单</button><button data-connectors="native" ${connectorLoading||!data||data.status==='disabled'?'disabled':''}>核对 Runtime 声明</button></div><p class="small muted">“核对 Runtime 声明”仅在你点击时读取原生执行目标；不测试外部连接，也不获取账户权限。</p>${connectorNative?`<div class="runtime-note"><strong>执行目标声明（非连接验证）</strong><p>来源：${escapeHtml(connectorNative.source)}<br>证据：${escapeHtml(connectorNative.evidence)}<br>未验证外部连接；此接口不提供操作输入结构。</p>${(connectorNative.targets||[]).map(target=>`<details><summary>${escapeHtml(target.id)} · ${escapeHtml(target.status)}</summary><div class="code-display">${safeJson({revision:target.revision,kind:target.kind,capabilities:target.capabilities})}</div></details>`).join('')||'<p>没有已声明的执行目标。</p>'}</div>`:''}`;}
let settingsData=null;
