function render(){if(authEnded)return;const focus=document.activeElement?.id;const start=document.activeElement?.selectionStart;const end=document.activeElement?.selectionEnd;const background=$('background-task')?.checked;nav();$('content').innerHTML=({chat,tasks,computer,memory,files,settings}[view])();if(view==='chat')renderAttachmentPanel();if(view==='settings'){if(settingsData)renderModelSettings();renderOwnerSessions();renderConnectors();}if(view==='computer')updateComputer();if(view==='tasks'){loadReminders();loadCalendars();loadProposals();}if(view==='files')loadArtifacts();if(background&&$('background-task')&&!$('background-task').disabled)$('background-task').checked=true;if(focus&&$(focus)){ $(focus).focus();if(typeof start==='number')$(focus).setSelectionRange?.(start,end);}}
function formatTime(value){const d=new Date(typeof value==='number'&&value<1e12?value*1000:value);return Number.isNaN(d.getTime())?String(value):d.toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});}
async function request(path,method='GET',body){const headers={'Accept':'application/json'};if(method!=='GET'){headers['Content-Type']='application/json';headers['x-opendots-csrf']=state.csrfToken||'';}const response=await appFetch(path,{method,headers,credentials:'same-origin',...(body===undefined?{}:{body:JSON.stringify(body)})});let data;try{data=await response.json()}catch{throw new Error('服务返回了无法识别的响应')}if(authEnded)throw new Error('登录已失效');if(!response.ok){const error=new Error(data.error?.message||data.message||data.error||`请求失败 (${response.status})`);error.status=response.status;error.code=data.code;throw error;}return data;}
async function loadState(force=false){if(loadInFlight||authEnded)return;loadInFlight=true;try{const next=await request('/api/state');if(authEnded)return;const encoded=JSON.stringify(next);state={...next,messages:Array.isArray(next.messages)?next.messages:[],jobs:Array.isArray(next.jobs)?next.jobs:[],approvals:Array.isArray(next.approvals)?next.approvals:[]};if(voiceSession?.kind==='stream'&&voiceSession.identity!==connectorSessionIdentity()){closeModal();toast('登录会话已变化，听写已取消。');}$('connection-error').hidden=true;if($('calendar-proposal-notice'))$('calendar-proposal-notice').innerHTML=proposalNotice().replace(/^<div id="calendar-proposal-notice">|<\/div>$/g,'');if($('computer-approval-notice'))$('computer-approval-notice').innerHTML=computerApprovalNotice().replace(/^<div id="computer-approval-notice">|<\/div>$/g,'');if(view==='tasks'&&$('task-list')){$('task-list').innerHTML=state.jobs.length?state.jobs.map(jobCard).join(''):empty('还没有任务','在对话中发起真实后台任务。');if($('approval-list'))$('approval-list').innerHTML=pendingApprovals().map(a=>`<div class="panel panel-pad approval"><p>${escapeHtml(a.justification||'操作等待确认')}</p><button data-approval="${escapeHtml(a.id)}">查看并决定 →</button></div>`).join('')||empty('目前没有待审批操作','操作、目标和授权范围都会明确显示。');nav();}if(force||(encoded!==lastState&&!['settings','computer','tasks','files','memory'].includes(view))){lastState=encoded;if(!busy&&(!$('modalback').hidden||(view==='chat'&&(selectionBusy||uploadBusy||filePickerOpen)))){nav()}else if(!busy){if(view==='computer'&&rfb){nav();updateComputer()}else render()}}}catch(error){if(authEnded)return;$('connection-error').textContent='连接中断：'+error.message+'。未确认的操作不会自动重发。';$('connection-error').hidden=false;state.runtime={status:'unavailable',message:error.message};nav();if(force)render()}finally{loadInFlight=false}}
async function sendMessage(event){event.preventDefault();if(busy||!runtimeReady()||!attachmentsReady())return;const text=$('message-input').value.trim();if(!text){toast(activeAttachments().length?'请为附件补一句说明。':'请先输入消息。');return}const background=$('background-task').checked;const items=activeAttachments();if(background&&items.length){toast('后台任务暂不支持附件，请发送到当前对话。');return}const endpoint=background?'/api/jobs':'/api/chat';const attached=items.length?{draftKey:attachmentDraft.draftKey,uploadIds:items.map(i=>i.id)}:null;if(attached&&attached.uploadIds.some(id=>!id)){toast('请先完成附件暂存。');return}const existing=(state.commands||[]).find(c=>['pending','submitting','unknown'].includes(c.status)&&c.kind===(background?'objective':'chat')&&c.payload?.[background?'prompt':'text']===text&&(attached?c.payload?.draftKey===attached.draftKey&&JSON.stringify(c.payload?.uploadIds)===JSON.stringify(attached.uploadIds):!c.payload?.uploadIds));const key=attached&&attachmentDraft.commandKey?attachmentDraft.commandKey:existing?.key||(pendingSubmission?.text===text&&pendingSubmission.endpoint===endpoint&&JSON.stringify(pendingSubmission.uploadIds||null)===JSON.stringify(attached?.uploadIds||null)?pendingSubmission.key:crypto.randomUUID());if(attached&&pendingSubmission?.key===key&&pendingSubmission.text!==text){toast('未确认的附件消息已锁定，请恢复原始正文重试。');return}pendingSubmission={text,endpoint,key,...(attached||{})};if(attached){attachmentDraft.commandKey=key;attachmentRejection=null;try{saveAttachmentIdentities()}catch(error){attachmentDraft.commandKey=null;toast(error.message);return}}draft=text;busy=true;render();try{await request(endpoint,'POST',{[background?'prompt':'text']:text,idempotencyKey:key,...(attached||{})});draft='';pendingSubmission=null;if(attached){for(const item of attachmentItems)item.file=null;attachmentDraft=null;attachmentItems=[];try{saveAttachmentIdentities()}catch(error){toast(error.message)}}toast(background?'任务已提交，等待运行时进展':attached?'消息及所选附件已提交，等待真实回复':'消息已提交，等待真实回复');}catch(error){if(attached&&[400,409,410,413,415,422].includes(error.status)){attachmentRejection={key,status:error.status};try{saveAttachmentIdentities()}catch(storageError){toast(storageError.message)}}toast(error.message+'。原消息与附件顺序保持不变，请核查后重试。')}finally{busy=false;render();await loadState(true);await loadAttachments()}}
let taskInputSession=null;
function taskAttemptStorageKey(){const session=state.binding?.sessionId;if(!session)throw new Error('请先连接固定会话，再提交任务补充');return 'opendots:task-input:'+session;}
function readTaskAttempts(){try{const saved=JSON.parse(sessionStorage.getItem(taskAttemptStorageKey())||'[]');return Array.isArray(saved)?saved.filter(a=>typeof a.objectiveId==='string'&&typeof a.key==='string'&&Number.isSafeInteger(a.generation)):[]}catch{return []}}
function hasPendingTaskInput(objectiveId){if((state.commands||[]).some(c=>c.kind==='objective_input'&&c.payload?.objectiveId===objectiveId&&['pending','submitting','unknown'].includes(c.status)))return true;const local=readTaskAttempts().find(a=>a.objectiveId===objectiveId);if(!local)return false;const known=(state.commands||[]).find(c=>c.key===local.key);return !known||['pending','submitting','unknown'].includes(known.status);}
function saveTaskAttempt(v){const key=taskAttemptStorageKey();const rows=readTaskAttempts().filter(a=>a.objectiveId!==v.target.objectiveId);rows.push({objectiveId:v.target.objectiveId,generation:v.target.generation,key:v.key});try{sessionStorage.setItem(key,JSON.stringify(rows))}catch{throw new Error('无法保存非敏感重试编号，本次补充未发送。')}}
function clearTaskAttempt(key){try{const storageKey=taskAttemptStorageKey();sessionStorage.setItem(storageKey,JSON.stringify(readTaskAttempts().filter(a=>a.key!==key)))}catch{toast('无法清理本地重试编号；重新打开时会按服务器回执核查。')}}

async function openTaskInput(id){const modalToken=++modalGeneration;void cleanupVoice();try{const pending=(state.commands||[]).find(c=>c.kind==='objective_input'&&c.payload?.objectiveId===id&&['pending','submitting','unknown'].includes(c.status));let local=readTaskAttempts().find(a=>a.objectiveId===id);const known=local&&(state.commands||[]).find(c=>c.key===local.key);if(known&&['accepted','rejected'].includes(known.status)){clearTaskAttempt(local.key);local=null;}if(pending?.payload?.replyToRequestId){toast('这条原请求绑定了提问回复；当前界面不能核验提问正文，因此不重发。');return}const target=pending||local?{objectiveId:id,generation:pending?.payload.expectedGeneration??local.generation,available:true,status:'unconfirmed'}:await request('/api/jobs/'+encodeURIComponent(id)+'/input-target');if(modalToken!==modalGeneration)return;taskInputSession={target:JSON.parse(JSON.stringify(target)),text:pending?String(pending.payload.text||''):'',key:pending?.key||local?.key||crypto.randomUUID(),sent:Boolean(pending||local),needsOriginalText:Boolean(local&&!pending),definitiveRejection:false,error:''};renderTaskInput(true,modalToken);return taskInputSession;}catch(error){if(modalToken===modalGeneration)toast(error.message)}}
function renderTaskInput(open=false,expectedGeneration){const v=taskInputSession;if(!v||(!open&&v.modalGeneration!==modalGeneration))return;const t=v.target;const reason={resume_required:'任务已暂停或阻塞，请先明确恢复任务。',objective_terminal:'任务已经结束，不能继续补充。',objective_state_unconfirmed:'任务状态尚未确认。',directed_input_unavailable:'当前 Runtime 未提供定向输入能力。'}[t.reason]||'当前任务不能接收补充说明。';const html=`<span class="tag">${v.sent?'原请求 · ':''}执行代 ${escapeHtml(t.generation)}</span><h2>给这项任务补充说明</h2><p class="small muted">只发给你选中的任务执行代，不是全局打断。补充说明不会自动回答或清除待答问题，也不会恢复已暂停的任务。</p>${v.needsOriginalText?'<div class="runtime-note">已恢复原请求编号和执行代，但正文未保存在浏览器。请重新输入完全相同的原说明，或等待服务器回执；不会创建新编号或改投最新执行代。</div>':''}${!t.available?'<div class="runtime-note">'+escapeHtml(reason)+'</div>':''}<form id="task-input-form"><label class="form-field">补充内容<textarea id="task-input-text" name="text" class="voice-text" maxlength="4000" required ${v.sent&&!v.needsOriginalText?'readonly':''}>${escapeHtml(v.text)}</textarea></label>${v.error?'<div class="inline-error" role="alert">'+escapeHtml(v.error)+'</div>':''}<div class="modal-actions"><button type="button" data-action="close-modal">关闭</button>${v.definitiveRejection?'<button type="button" data-action="refresh-task-input">重新核对执行代</button>':''}<button type="submit" class="primary" ${!t.available||busy?'disabled':''}>${v.sent?'重试同一条补充':'发送这一次补充'}</button></div><p class="small muted">收到提交回执只表示已接收或排队，不代表说明已经应用或任务已完成。</p></form>`;if(open){if(openModal(html,{expectedGeneration}))v.modalGeneration=modalGeneration;}else $('modal').innerHTML=html;}
async function submitTaskInput(){const v=taskInputSession;if(!v||busy||!v.target.available)return;if(!v.sent||v.needsOriginalText)v.text=$('task-input-text').value.trim();if(!v.text||v.text.length>4000)return;try{saveTaskAttempt(v)}catch(error){v.error=error.message;renderTaskInput();return}v.needsOriginalText=false;v.sent=true;v.definitiveRejection=false;busy=true;renderTaskInput();try{await request('/api/jobs/'+encodeURIComponent(v.target.objectiveId)+'/input','POST',{text:v.text,idempotencyKey:v.key,expectedGeneration:v.target.generation});clearTaskAttempt(v.key);if(taskInputSession===v&&v.modalGeneration===modalGeneration)closeModal();toast('补充说明已接收，等待这项任务处理；尚不代表已经应用。')}catch(error){v.error=error.message+'。保留原执行代、正文和请求编号，不会自动改投新的任务。';v.definitiveRejection=[400,409,410,422].includes(error.status);if(taskInputSession===v)renderTaskInput()}finally{busy=false;if(taskInputSession===v)renderTaskInput();await loadState()}}
async function refreshTaskInput(){const v=taskInputSession;if(!v?.definitiveRejection||busy)return;const modalToken=modalGeneration;try{const current=await request('/api/state');if(taskInputSession!==v||modalToken!==modalGeneration)return;if(current.runtime?.status!=='ready'||current.binding?.sessionId!==state.binding?.sessionId)throw new Error('尚不能权威核对原请求，请保留原编号。');const command=(current.commands||[]).find(c=>c.key===v.key);if(command&&command.status!=='rejected')throw new Error('原请求仍需核查，不能改投新的执行代。');if(!window.confirm('重新读取当前任务执行代？原草稿不会自动发送，你需要重新确认。'))return;const text=v.text;state.commands=current.commands||[];clearTaskAttempt(v.key);const renewed=await openTaskInput(v.target.objectiveId);if(renewed&&taskInputSession===renewed&&!renewed.sent){renewed.text=text;renderTaskInput();}}catch(error){toast(error.message)}}
async function controlJob(id,action){const job=state.jobs.find(j=>String(j.id)===id);if(!job||busy||job.revision===undefined||job.status==='unknown')return;if(action==='cancel'&&!window.confirm('请求取消这项任务？已完成的外部操作不一定能撤销。'))return;busy=true;render();try{await request('/api/jobs/'+encodeURIComponent(id)+'/control','POST',{action,expectedRevision:job.revision,idempotencyKey:crypto.randomUUID()});toast('控制请求已提交，等待运行时确认')}catch(error){toast(error.message)}finally{busy=false;await loadState(true);render()}}
function openModal(html,options={}){if(authEnded)return false;if(options.expectedGeneration!==undefined&&options.expectedGeneration!==modalGeneration)return false;if(!options.voice)void cleanupVoice();cleanupComputerApproval();calendarPreview=null;activeProposal=null;activeDocument=null;artifactEditor=null;modalGeneration++;modalReturnFocus=document.activeElement;$('modal').innerHTML=html;$('modalback').hidden=false;$('modalback').style.display='flex';$('modal').focus();return true;}
function closeModal(){activeDocument=null;artifactEditor=null;activeProposal=null;cleanupComputerApproval();$('modal').innerHTML='';modalGeneration++;void cleanupVoice();activeApproval=null;taskInputSession=null;calendarPreview=null;$('modalback').hidden=true;$('modalback').style.display='none';modalReturnFocus?.focus?.()}
function openApproval(id){const a=pendingApprovals().find(a=>String(a.id)===id);if(!a)return;activeApproval=JSON.parse(JSON.stringify(a));openModal(`<span class="tag amber">等待你的确认</span><h2>确认这一次操作</h2><p>${escapeHtml(a.justification||'检查目标、操作和数据范围，再决定是否授权。')}</p><div class="approval-detail"><strong class="small">操作与请求参数</strong><div class="code-display">${safeJson({action:a.action,requested:a.requested,target:a.target_id,thread:a.thread_id,revision:a.revision})}</div><p>仅授权本次动作。参数或版本变化需要重新审批。</p></div><div class="modal-actions"><button data-action="close-modal">返回</button><button data-decision="deny" ${a.revision===undefined?'disabled':''}>拒绝</button><button class="primary" data-decision="allow_once" ${a.revision===undefined||!a.available_scopes?.includes('once')?'disabled':''}>允许这一次</button></div>`)}
async function decideApproval(decision){const a=activeApproval;if(!a||busy||a.revision===undefined)return;if(decision==='allow_once'&&!a.available_scopes?.includes('once')){toast('本次操作不支持一次性授权');return;}busy=true;for(const b of $('modal').querySelectorAll('button'))b.disabled=true;try{await request('/api/approvals/'+encodeURIComponent(a.id)+'/decision','POST',{decision,expectedRevision:a.revision,idempotencyKey:crypto.randomUUID()});closeModal();toast('审批决定已提交；操作结果仍以运行时回执为准')}catch(error){toast(error.message);for(const b of $('modal').querySelectorAll('button'))b.disabled=false}finally{busy=false;await loadState(true)}}
let attachmentDraft=null,attachmentItems=[],attachmentInventory=[],attachmentLimits=null,uploadBusy=false,selectionBusy=false,filePickerOpen=false,uploadController=null,activeUploadKey=null,uploadStopRequested=false,attachmentResumeKey=null,attachmentRejection=null;
function attachmentStorageKey(){return 'opendots:attachment-draft:'+String(state.binding?.sessionId||'unbound');}
function saveAttachmentIdentities(){if(!state.binding?.sessionId)throw new Error('请先连接固定会话，再选择附件');const value=attachmentDraft?{draftKey:attachmentDraft.draftKey,commandKey:attachmentDraft.commandKey||null,rejection:attachmentRejection?.key===attachmentDraft.commandKey&&[400,409,410,413,415,422].includes(attachmentRejection.status)?{key:attachmentRejection.key,status:attachmentRejection.status}:null,uploads:attachmentItems.map(i=>({uploadKey:i.uploadKey,id:i.id||null}))}:null;try{if(value)sessionStorage.setItem(attachmentStorageKey(),JSON.stringify(value));else sessionStorage.removeItem(attachmentStorageKey())}catch{throw new Error('无法保存附件重试编号；为避免重复创建，暂不上传。')}}
function restoreAttachmentIdentities(){if(attachmentDraft||!state.binding?.sessionId)return;try{const saved=JSON.parse(sessionStorage.getItem(attachmentStorageKey())||'null');if(saved&&typeof saved.draftKey==='string'&&Array.isArray(saved.uploads)){attachmentDraft={draftKey:saved.draftKey,commandKey:saved.commandKey||null};attachmentRejection=saved.rejection?.key===saved.commandKey&&[400,409,410,413,415,422].includes(saved.rejection?.status)?{key:saved.rejection.key,status:saved.rejection.status}:null;attachmentItems=saved.uploads.filter(i=>typeof i.uploadKey==='string').map(i=>({uploadKey:i.uploadKey,id:typeof i.id==='string'?i.id:null,status:'needs_reselect',file:null}));}}catch{toast('附件恢复编号无法读取；不会自动创建新上传。')}}
function activeAttachments(){return attachmentItems.filter(i=>i.status!=='cancelled');}
function attachmentsReady(){const items=activeAttachments();return !uploadBusy&&!selectionBusy&&!items.some(i=>i.status==='cancelling')&&(!items.length||Boolean(attachmentDraft?.commandKey)||items.every(i=>i.status==='ready'&&!i.sealed));}
function attachmentPanel(){const items=activeAttachments();const labels={local:'仅本地选择',needs_reselect:'需要重选原文件',pending:'暂存申请中',uploading:'正在暂存',ready:'已暂存 · 尚未发送',unknown:'上传结果待核查',missing:'已过期或不存在',cancelling:'取消待确认',cancelled:'已取消',consumed:'已作为消息附件提交'};return `<div class="attachment-panel">${items.length?`<p class="small muted">${attachmentDraft?.commandKey?'消息和附件顺序已锁定。未确认时只重试原请求。':'附件会暂存到本机配置的 Morphz；暂存不等于提交给模型。点击发送才会一起提交。'}</p>`:''}${attachmentDraft?.commandKey&&attachmentRejection?.key===attachmentDraft.commandKey?'<div class="runtime-note">发送被明确拒绝。先核对服务器未接收且草稿未锁定，再解除本地冻结。<button type="button" data-action="unlock-rejected-attachments">核对后解除冻结</button></div>':''}${items.map(i=>`<div class="attachment-row"><div><strong class="small">${escapeHtml(i.name||'已保存的附件编号')}</strong><div class="small muted">${escapeHtml(labels[i.status]||i.status)}${i.sizeBytes?' · '+Math.ceil(i.sizeBytes/1024)+' KB':''}${i.offset&&i.sizeBytes?' · '+Math.floor(i.offset/i.sizeBytes*100)+'%':''}</div>${i.error?`<div class="inline-error">${escapeHtml(i.error)}</div>`:''}</div><div class="attachment-actions">${uploadBusy&&activeUploadKey===i.uploadKey?'<button type="button" data-action="stop-upload-transfer">停止本次传输</button>':''}${!attachmentDraft?.commandKey&&!i.sealed?`${i.status==='local'?`<button type="button" data-upload="${escapeHtml(i.uploadKey)}" ${uploadBusy?'disabled':''}>暂存到本机 Morphz</button>`:!['ready','consumed','missing','cancelling'].includes(i.status)?`<button type="button" data-resume-upload="${escapeHtml(i.uploadKey)}" ${uploadBusy?'disabled':''}>${i.file?'核对并继续':'重选原文件继续'}</button>`:''}<button type="button" data-cancel-upload="${escapeHtml(i.uploadKey)}" ${uploadBusy||i.status==='consumed'?'disabled':''}>${i.status==='local'?'移除本地选择':'取消暂存'}</button>`:''}</div></div>`).join('')}${!items.length&&attachmentInventory.some(i=>!i.sealed&&!['consumed','cancelled'].includes(i.status))?'<button type="button" data-action="restore-upload-draft">恢复已有暂存草稿</button>':''}<p class="small muted">PNG / JPEG / PDF / TXT；最多 4 个、单个 10 MiB、合计 20 MiB。刷新后不保留文件字节，未完成上传需重选同一文件。暂不支持后台任务附件。</p></div>`;}
function renderAttachmentPanel(){if(authEnded)return;if(view!=='chat'||!$('attachment-panel'))return;$('attachment-panel').innerHTML=attachmentPanel();const input=$('attachment-input');if(input)input.disabled=uploadBusy||selectionBusy||Boolean(attachmentDraft?.commandKey)||!attachmentLimits;const send=$('chat-form')?.querySelector?.('[type="submit"]');if(send)send.disabled=busy||!runtimeReady()||!attachmentsReady();const background=$('background-task');if(background){background.disabled=activeAttachments().length>0;if(background.disabled)background.checked=false;}if($('message-input'))$('message-input').readOnly=Boolean(attachmentDraft?.commandKey&&(pendingSubmission?.key===attachmentDraft.commandKey||(state.commands||[]).some(c=>c.key===attachmentDraft.commandKey)));}
async function loadAttachments(){if(!state.binding?.sessionId)return;try{restoreAttachmentIdentities();const result=await request('/api/uploads');attachmentInventory=result.uploads||[];attachmentLimits=result.limits;for(const item of attachmentItems){const saved=attachmentInventory.find(i=>i.draftKey===attachmentDraft.draftKey&&((item.id&&i.id===item.id)||i.uploadKey===item.uploadKey));if(saved)Object.assign(item,saved);}const command=attachmentDraft?.commandKey&&(state.commands||[]).find(c=>c.key===attachmentDraft.commandKey);if(command?.status==='accepted'){attachmentDraft=null;attachmentItems=[];saveAttachmentIdentities();}else if(command&&Array.isArray(command.payload?.uploadIds)){restoreAttachmentCommand(command);if($('message-input'))$('message-input').value=draft;}renderAttachmentPanel()}catch(error){if(view==='chat')toast('附件状态无法确认：'+error.message)}}
function fileMediaType(file){if(file.type)return file.type;const extension=file.name.toLowerCase().split('.').pop();return {png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',pdf:'application/pdf',txt:'text/plain'}[extension]||'';}
async function inspectSelectedFile(file,isCurrent=()=>!authEnded){const limits=attachmentLimits;if(!limits)throw new Error('附件服务尚未就绪');const mediaType=fileMediaType(file);if(!file.name||file.name!==file.name.trim()||[...file.name].length>255||/[\\/\x00-\x1f\x7f]/.test(file.name))throw new Error('文件名不能包含路径、控制字符或首尾空格，且最多 255 个字符');if(!limits.mediaTypes.includes(mediaType)||file.size<1||file.size>limits.maximumBytes)throw new Error('只支持 PNG、JPEG、PDF、TXT，且每个文件必须在 1 字节到 10 MiB 内');const bytes=await file.arrayBuffer();if(!isCurrent())throw new Error('登录会话已变化，所选文件已丢弃');const digest=await crypto.subtle.digest('SHA-256',bytes);if(!isCurrent())throw new Error('登录会话已变化，所选文件已丢弃');const sha256=Array.from(new Uint8Array(digest),v=>v.toString(16).padStart(2,'0')).join('');return {name:file.name,mediaType,sizeBytes:file.size,sha256,file};}
async function chooseAttachments(files){if(authEnded)return;const identity=JSON.stringify([state.authentication?.session?.id,state.binding?.sessionId]);const isCurrent=()=>!authEnded&&identity===JSON.stringify([state.authentication?.session?.id,state.binding?.sessionId]);if(uploadBusy||selectionBusy||attachmentDraft?.commandKey)return;selectionBusy=true;renderAttachmentPanel();try{if(attachmentResumeKey){const item=attachmentItems.find(i=>i.uploadKey===attachmentResumeKey);attachmentResumeKey=null;if(!item||files.length!==1)throw new Error('继续上传时，请只重选一个原文件');const selected=await inspectSelectedFile(files[0],isCurrent);if(!isCurrent())return;if(item.sha256&&(selected.sha256!==item.sha256||selected.sizeBytes!==item.sizeBytes||selected.name!==item.name||selected.mediaType!==item.mediaType))throw new Error('这不是原文件：名称、类型、大小或 SHA-256 不一致');Object.assign(item,selected);if(!item.id){const matched=attachmentInventory.find(i=>i.uploadKey===item.uploadKey&&i.draftKey===attachmentDraft.draftKey);if(matched){if(matched.sha256!==selected.sha256||matched.name!==selected.name||matched.sizeBytes!==selected.sizeBytes||matched.mediaType!==selected.mediaType)throw new Error('所选文件与原暂存声明不一致');Object.assign(item,matched);}}saveAttachmentIdentities();renderAttachmentPanel();toast('原文件已在本地核对。点击“核对并继续”才传输剩余字节。');return;}const current=activeAttachments();if(current.some(i=>!i.sizeBytes))throw new Error('请先重选并核对已保存的原文件，再添加附件');if(current.length+files.length>attachmentLimits.maximumFiles)throw new Error('最多选择四个附件');if(current.reduce((n,i)=>n+(i.sizeBytes||0),0)+files.reduce((n,f)=>n+f.size,0)>attachmentLimits.maximumDraftBytes)throw new Error('附件合计不能超过 20 MiB');for(const file of files){const selected=await inspectSelectedFile(file,isCurrent);if(!isCurrent())return;if(!attachmentDraft)attachmentDraft={draftKey:crypto.randomUUID(),commandKey:null};attachmentItems.push({...selected,uploadKey:crypto.randomUUID(),id:null,status:'local',offset:0});}saveAttachmentIdentities();renderAttachmentPanel()}catch(error){toast(error.message)}finally{selectionBusy=false;renderAttachmentPanel();}}
async function uploadAttachment(key){const item=attachmentItems.find(i=>i.uploadKey===key);if(!item||uploadBusy||attachmentDraft?.commandKey||item.sealed)return;if(item.status==='cancelling'){toast('取消结果尚未确认，请先核对取消状态。');return}if(!item.file){attachmentResumeKey=key;filePickerOpen=true;$('attachment-input').multiple=false;$('attachment-input').click();return;}try{saveAttachmentIdentities()}catch(error){toast(error.message);return}uploadBusy=true;activeUploadKey=key;uploadStopRequested=false;item.error='';renderAttachmentPanel();try{if(!item.id){item.status='pending';renderAttachmentPanel();const created=await request('/api/uploads','POST',{draftKey:attachmentDraft.draftKey,uploadKey:item.uploadKey,name:item.name,mediaType:item.mediaType,sizeBytes:item.sizeBytes,sha256:item.sha256});Object.assign(item,created);saveAttachmentIdentities();}else Object.assign(item,await request('/api/uploads/'+encodeURIComponent(item.id)+'/reconcile','POST',{}));if(['missing','cancelled','consumed'].includes(item.status))throw new Error('原暂存已过期、取消或提交；不会自动创建替代上传');while(item.status==='uploading'||item.status==='pending'){if(uploadStopRequested)throw new Error('已停止本次传输，原暂存保留；核对后可以继续');if(item.offset>=item.sizeBytes)break;uploadController=new AbortController();const chunk=item.file.slice(item.offset,Math.min(item.sizeBytes,item.offset+attachmentLimits.maximumChunkBytes));const response=await appFetch('/api/uploads/'+encodeURIComponent(item.id)+'/content',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/octet-stream','x-opendots-csrf':state.csrfToken||'','x-opendots-upload-offset':String(item.offset)},body:chunk,signal:uploadController.signal});let next;try{next=await response.json()}catch{throw new Error('未收到可核验的上传回执')}if(!response.ok)throw new Error(next.error?.message||next.error||'分块上传结果待核查');Object.assign(item,next);renderAttachmentPanel();}if(item.status==='ready'){item.file=null;toast('附件已暂存，尚未提交给模型。');}else if(item.status!=='uploading')throw new Error('暂存状态尚未确认，请核对后继续');}catch(error){item.error=error.message;if(!item.id&&[400,409,410,413,415,422].includes(error.status))item.declarationRejected=true;if(!['missing','cancelled','consumed'].includes(item.status))item.status='unknown';toast('上传未确认，保留原编号；不会自动重传或创建新暂存。');}finally{uploadBusy=false;activeUploadKey=null;uploadController=null;try{saveAttachmentIdentities()}catch(error){toast(error.message)}renderAttachmentPanel();}}
async function cancelAttachment(key){const item=attachmentItems.find(i=>i.uploadKey===key);if(!item||uploadBusy||attachmentDraft?.commandKey||item.sealed)return;try{if(item.status==='local'){attachmentItems=attachmentItems.filter(i=>i!==item);}else{if(!item.id){const inventory=await request('/api/uploads');const found=(inventory.uploads||[]).find(i=>i.draftKey===attachmentDraft.draftKey&&i.uploadKey===item.uploadKey);if(found)Object.assign(item,found);else if(item.declarationRejected){attachmentItems=attachmentItems.filter(i=>i!==item);if(!attachmentItems.length)attachmentDraft=null;saveAttachmentIdentities();renderAttachmentPanel();return;}else throw new Error('暂存申请结果未知，请先核对或重选原文件以找回原编号，再取消。');}const result=await request('/api/uploads/'+encodeURIComponent(item.id)+'/cancel','POST',{});Object.assign(item,result);item.file=null;if(item.status!=='cancelled')throw new Error('取消尚未确认；已提交资源不能通过取消暂存删除');attachmentItems=attachmentItems.filter(i=>i!==item);}if(!attachmentItems.length)attachmentDraft=null;saveAttachmentIdentities();renderAttachmentPanel()}catch(error){toast(error.message)}}
async function unlockRejectedAttachmentDraft(){const frozen=attachmentDraft?.commandKey;if(!frozen||attachmentRejection?.key!==frozen)return;try{const current=await request('/api/state');if(current.runtime?.status!=='ready'||current.binding?.sessionId!==state.binding?.sessionId)throw new Error('运行时状态尚不能确认，继续保留原请求');if((current.commands||[]).some(c=>c.key===frozen))throw new Error('服务器已保存该消息请求，不能修改原附件或正文');const inventory=await request('/api/uploads');const rows=activeAttachments().map(i=>(inventory.uploads||[]).find(row=>row.id===i.id&&row.draftKey===attachmentDraft.draftKey));if(rows.some(row=>!row||row.sealed||row.status==='consumed')||!rows.length)throw new Error('附件未确认可编辑，原冻结仍然保留');if(attachmentDraft?.commandKey!==frozen)return;for(let i=0;i<rows.length;i++)Object.assign(activeAttachments()[i],rows[i]);attachmentDraft.commandKey=null;attachmentRejection=null;pendingSubmission=null;saveAttachmentIdentities();renderAttachmentPanel();toast('已确认没有接收该请求，附件草稿可重新处理。')}catch(error){toast(error.message)}}
function restoreAttachmentCommand(command){const p=command.payload;if(!p?.draftKey||!Array.isArray(p.uploadIds))return false;attachmentDraft={draftKey:p.draftKey,commandKey:command.key};attachmentItems=p.uploadIds.map(id=>({...attachmentInventory.find(i=>i.id===id),id,uploadKey:attachmentInventory.find(i=>i.id===id)?.uploadKey||id,file:null,status:attachmentInventory.find(i=>i.id===id)?.status||'unknown'}));draft=String(p.text||'');pendingSubmission={text:draft,endpoint:'/api/chat',key:command.key,draftKey:p.draftKey,uploadIds:[...p.uploadIds]};saveAttachmentIdentities();return true;}
function restoreStagedDraft(){const row=attachmentInventory.find(i=>!i.sealed&&!['consumed','cancelled'].includes(i.status));if(!row)return;attachmentDraft={draftKey:row.draftKey,commandKey:null};attachmentItems=attachmentInventory.filter(i=>i.draftKey===row.draftKey&&!['consumed','cancelled'].includes(i.status)).map(i=>({...i,uploadKey:i.uploadKey||i.id,file:null}));saveAttachmentIdentities();renderAttachmentPanel();}

let voiceCapability=null,voiceSession=null,voiceGeneration=0;
async function voiceCapabilities(){voiceCapability=await request('/api/voice');return voiceCapability;}
function streamVoiceCurrent(v){return Boolean(v&&voiceSession===v&&!authEnded&&!v.disposed&&v.identity===connectorSessionIdentity());}
function cancelStreamTransport(v){if(!v?.streamId||v.streamCancelSent)return;v.streamCancelSent=true;clearTimeout(v.streamTimer);v.streamControllers?.forEach(controller=>controller.abort());v.streamControllers?.clear();void fetch('/api/voice/stream',{method:'POST',credentials:'same-origin',keepalive:true,headers:{'Content-Type':'application/json','x-opendots-csrf':v.streamCsrf||''},body:JSON.stringify({id:v.streamId,action:'cancel'})}).catch(()=>{});}
async function streamVoiceRequest(v,body,frameSignal){if(!streamVoiceCurrent(v))throw new Error('听写会话已结束');const controller=new AbortController();v.streamControllers.add(controller);const abort=()=>controller.abort();if(frameSignal?.aborted)controller.abort();else frameSignal?.addEventListener('abort',abort,{once:true});try{const response=await appFetch('/api/voice/stream',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','x-opendots-csrf':v.streamCsrf},body:JSON.stringify({id:v.streamId,...body}),signal:controller.signal});const data=await response.json();if(!response.ok)throw new Error(data.code||data.error?.code||data.error||'听写请求失败');if(!streamVoiceCurrent(v))throw new Error('听写会话已变化');if(data.id!==v.streamId||!Number.isSafeInteger(data.revision)||data.duplex!==false||data.reviewRequired!==true||data.sentToChat!==false||!['opening','listening','finishing','complete','cancelled','error'].includes(data.status)||!Number.isSafeInteger(data.receivedSequence)||typeof data.text!=='string')throw new Error('听写响应格式未通过核对');return data;}finally{frameSignal?.removeEventListener('abort',abort);v.streamControllers.delete(controller);}}
function applyStreamVoice(v,data){if(!streamVoiceCurrent(v)||v.streamFinished||data.revision<v.streamRevision)return;v.streamRevision=data.revision;v.remoteStatus=data.status;v.text=data.text;v.streamExpiresAt=data.expiresAt;if(data.status==='error')throw new Error(data.errorCode||'听写供应商返回错误');if(data.status==='cancelled')throw new Error('听写已经取消');if(data.status==='complete'){v.streamFinished=true;clearTimeout(v.streamTimer);void v.capture?.cancel().catch(()=>{});v.status='review';v.capture=null;}else if(data.status==='finishing'){v.status='stream-finishing';void stopRemoteFinishingCapture(v);}renderVoice();}
async function stopRemoteFinishingCapture(v){if(v.remoteStopStarted)return;v.remoteStopStarted=true;v.streamStopStarted=true;clearTimeout(v.streamTimer);const capture=v.capture;try{await capture?.stop();if(v.capture===capture)v.capture=null;}catch(error){await failStreamVoice(v,error);}}
async function failStreamVoice(v,error){if(!v||v.streamFinished||v.failing)return;v.failing=true;cancelStreamTransport(v);await v.capture?.cancel().catch(()=>{});v.capture=null;v.text='';if(voiceSession!==v||authEnded||v.disposed)return;v.status='stream-error';v.error='流式听写已停止，未确认文字已丢弃：'+(error?.message||'连接异常')+'。不会自动重连或重发音频。';renderVoice();}
async function readStreamVoice(v){while(streamVoiceCurrent(v)&&!v.streamFinished&&!v.streamCancelSent){try{const data=await streamVoiceRequest(v,{action:'read',after:v.streamRevision});applyStreamVoice(v,data);}catch(error){await failStreamVoice(v,error);return;}}}
async function streamCaptureFactory(){return (await import('/voice-stream-capture.js')).createVoiceStreamCapture;}
async function startStreamVoice(){const v=voiceSession;if(!v||v.kind!=='stream'||v.status!=='idle'||!v.cap.stream?.available||v.cap.stream?.streamingDictation!==true||v.identity!==connectorSessionIdentity())return;v.status='stream-opening';v.error='';v.streamId=crypto.randomUUID();v.streamCsrf=state.csrfToken||'';v.streamControllers=new Set();v.streamRevision=0;v.streamSequence=0;v.streamFinished=false;v.streamCancelSent=false;v.maximumSeconds=Math.min(120,Math.max(1,v.cap.stream.maximumSeconds||60));renderVoice();try{const createVoiceStreamCapture=await streamCaptureFactory();if(!streamVoiceCurrent(v))return;const opened=await streamVoiceRequest(v,{action:'open',consent:true});applyStreamVoice(v,opened);if(!streamVoiceCurrent(v)||v.streamFinished)return;if(opened.status==='finishing'){void readStreamVoice(v);return;}if(opened.status!=='listening')throw new Error('供应商尚未就绪，未开启麦克风');const remaining=Number(opened.expiresAt)-Date.now();if(!Number.isFinite(remaining)||remaining<1500)throw new Error('听写有效时间不足');v.capture=createVoiceStreamCapture({maxSeconds:Math.max(1,Math.min(v.maximumSeconds,Math.floor(remaining/1000)-1)),onFrame:async(bytes,signal)=>{if(!streamVoiceCurrent(v))throw new Error('听写会话已结束');if(v.streamFinished||v.remoteStatus==='finishing')return;if(!bytes||bytes.byteLength<2||bytes.byteLength>6400||bytes.byteLength%2)throw new Error('听写音频帧大小不正确');const sequence=++v.streamSequence;let result;try{result=await streamVoiceRequest(v,{action:'push',sequence,data:Array.from(bytes)},signal);}catch(error){if(v.remoteStatus==='finishing'&&error.message==='voice_stream_not_listening')return;throw error;}if(result.receivedSequence<sequence)throw new Error('音频帧回执未确认');applyStreamVoice(v,result);},onLimit:()=>{if(streamVoiceCurrent(v))void finishStreamVoice();},onError:error=>{void failStreamVoice(v,error);}});v.streamTimer=setTimeout(()=>{void finishStreamVoice();},Math.max(1,Math.min(v.maximumSeconds*1000,remaining-1000)));void readStreamVoice(v);await v.capture.start();if(!streamVoiceCurrent(v)||v.streamFinished){await v.capture?.cancel();return;}if(!v.streamStopStarted){v.status='stream-listening';renderVoice();}}catch(error){if(error?.name==='AbortError'&&v.streamStopStarted&&v.status==='stream-finishing'&&!v.streamCancelSent&&streamVoiceCurrent(v))return;await failStreamVoice(v,error);}}
async function finishStreamVoice(){const v=voiceSession;if(!streamVoiceCurrent(v)||!['stream-listening','stream-opening'].includes(v.status)||v.streamStopStarted)return;v.streamStopStarted=true;v.status='stream-finishing';renderVoice();try{await v.capture?.stop();if(!streamVoiceCurrent(v)||v.streamFinished)return;v.capture=null;if(v.remoteStatus==='finishing')return;const result=await streamVoiceRequest(v,{action:'finish'});applyStreamVoice(v,result);}catch(error){await failStreamVoice(v,error);}}
function selectStreamingVoice(){const v=voiceSession;if(!v||v.kind!=='record'||v.status!=='idle'||v.cap.stream?.available!==true||v.cap.stream.streamingDictation!==true)return;v.kind='stream';v.identity=connectorSessionIdentity();renderVoice();}
async function cleanupVoice(){voiceGeneration++;const v=voiceSession;voiceSession=null;if(!v)return;v.disposed=true;cancelStreamTransport(v);v.text='';v.blob=null;v.controller?.abort();if(v.capture)await v.capture.cancel().catch(()=>{});v.capture=null;v.blob=null;v.text='';if(v.audio){v.audio.pause();v.audio.removeAttribute?.('src');v.audio.load?.();v.audio=null;}if(v.audioUrl){URL.revokeObjectURL(v.audioUrl);v.audioUrl=null;}}
async function openVoice(){const modalToken=++modalGeneration;await cleanupVoice();const generation=voiceGeneration;try{const cap=await voiceCapabilities();if(generation!==voiceGeneration||modalToken!==modalGeneration)return;voiceSession={kind:'record',status:'idle',cap,text:'',blob:null,capture:null,error:''};renderVoice(true,modalToken)}catch(error){toast(error.message)}}
async function openReadAloud(id){const message=state.messages.find(m=>String(m.id)===id&&m.role==='assistant'&&!m.draft);if(!message)return;const modalToken=++modalGeneration;await cleanupVoice();const generation=voiceGeneration;try{const cap=await voiceCapabilities();if(generation!==voiceGeneration||modalToken!==modalGeneration)return;voiceSession={kind:'read',status:'idle',cap,messageId:id,text:'',blob:null,error:''};renderVoice(true,modalToken)}catch(error){toast(error.message)}}
function renderVoice(open=false,expectedGeneration){const v=voiceSession;if(!v)return;const cap=v.cap;const provider=escapeHtml(cap.provider?.label||'未配置供应商');const destination=escapeHtml(cap.provider?.destination||'未配置');const available=Boolean(cap.available);let body=`<span class="eyebrow">OPT-IN WEB VOICE</span><h2>${v.kind==='read'?'朗读这条回复':'用声音，把想法说出来'}</h2><p class="small muted">供应商：${provider} · 数据目的地：${destination}</p><p class="small muted">${v.kind==='stream'?'这是单向流式听写，不是电话或双向实时通话。':'这是单次录音 / 朗读功能，不是电话或双向实时通话。'}服务按供应商规则计费；配置可用不代表已完成真实验证。取消会停止本地操作，但已发给供应商的数据可能已被处理。opendots 不持久保存录音；供应商的数据保留遵循其自身政策。</p>`;if(!available)body+=`<div class="runtime-note">${escapeHtml(cap.message||'语音尚未配置')}。麦克风和音频传输均未开启。</div>`;if(v.error)body+=`<p class="inline-error" role="alert">${escapeHtml(v.error)}</p>`;
if(v.kind==='stream'&&v.status!=='review'){body+=`<p>流式听写：点击开始后，麦克风音频会持续发送给 ${provider}（${destination}），直到停止或取消。可能按供应商规则收费。最多 ${escapeHtml(v.cap.stream?.maximumSeconds||60)} 秒，硬上限 120 秒。</p><p class="small muted">单向听写，不是双向通话（duplex: false）。停止只结束听写，不取消已有模型任务；不会自动发送消息、朗读或重连。</p><div class="code-display" role="status" aria-live="polite">${escapeHtml(v.text||'尚无转写文字')}</div><p class="small muted">${v.status==='stream-listening'?'正在持续传输音频 · 上方文字为未完成草稿':v.status==='stream-finishing'?'麦克风已停止 / 正在收尾，等待最终文字':v.status==='stream-opening'?'正在开启听写与请求麦克风权限…':v.status==='stream-error'?'已停止；请关闭后重新选择，未发送聊天消息':'尚未开启麦克风或供应商连接'}</p><div class="modal-actions"><button data-action="close-modal">取消并丢弃</button>${v.status==='idle'?'<button class="primary" data-voice="stream-start">同意持续传输并开始听写</button>':`<button data-voice="stream-stop" ${v.status!=='stream-listening'?'disabled':''}>停止并等待最终文字</button>`}</div>`;}else if(v.kind==='read'){body+=`<p>点击下方按钮后，这条已提交的助理回复文字会发给 ${provider} 生成音频。不会发送未完成的草稿。</p>${v.status==='playing'?'<audio id="voice-playback" controls aria-label="助理回复朗读"></audio>':''}<div class="modal-actions"><button data-action="close-modal">关闭并停止</button><button class="primary" data-voice="read" ${!available||!cap.operations?.readAloud||v.status!=='idle'?'disabled':''}>同意发送这条回复并朗读</button></div>`;}else if(v.status==='review'){body+=`${v.kind==='stream'?'<p class="small muted">已收到最终转写。麦克风已停止；下面是可编辑、尚未发送的文字。</p>':''}<label class="form-field">转写草稿（发送前请核对）<textarea id="voice-transcript" class="voice-text" ${v.attempt?'readonly':''}>${escapeHtml(v.text)}</textarea></label><p class="small muted">本页录音副本已丢弃，供应商保留遵循其政策。文字不会自动发给助理。</p><div class="modal-actions"><button data-action="close-modal">丢弃草稿</button><button class="primary" data-voice="send" ${busy?'disabled':''}>${v.attempt?'重试原消息':'确认发送到对话'}</button></div>`;}else if(v.status==='captured'){body+=`<p>录音只暂存在本页内存。下一步会将这段音频发送到 ${destination}，由 ${provider} 转写。</p><div class="modal-actions"><button data-action="close-modal">取消并丢弃</button><button class="primary" data-voice="transcribe">同意发送录音并转写</button></div>`;}else{const recording=v.status==='recording';body+=`<div class="voice-orb" aria-hidden="true"></div><p role="status">${v.status==='requesting'?'等待浏览器麦克风许可…':recording?'正在本地录音，最多 '+Math.min(10,cap.capture?.maximumSeconds||10)+' 秒':v.status==='transcribing'?'正在请求转写，可取消；不会自动重试':v.status==='stopping'?'正在停止麦克风…':'录音开始前会请求麦克风权限；停止后还需你确认才上传。'}</p><div class="modal-actions"><button data-action="close-modal">取消并丢弃</button><button class="primary" data-voice="${recording?'stop':'record'}" ${!available||!cap.operations?.transcribe||!['idle','recording'].includes(v.status)?'disabled':''}>${recording?'停止录音':'开始本地录音'}</button>${v.status==='idle'&&cap.stream?.available===true&&cap.stream.streamingDictation===true?'<button data-voice="stream-choice">选择实时听写（持续传输）</button>':''}</div>`;}if(open)openModal(body,{voice:true,expectedGeneration});else $('modal').innerHTML=body;}
async function recordVoice(){const v=voiceSession;if(!v||!v.cap.available||!v.cap.operations?.transcribe||v.status!=='idle')return;const generation=voiceGeneration;v.status='requesting';v.error='';renderVoice();try{const {createVoiceCapture}=await import('/voice-capture.js');if(generation!==voiceGeneration)return;v.capture=createVoiceCapture({maxSeconds:Math.min(10,v.cap.capture.maximumSeconds),onLimit:()=>{if(generation===voiceGeneration)void stopVoice()}});await v.capture.start();if(generation!==voiceGeneration){await v.capture.cancel();return}v.status='recording';renderVoice()}catch(error){if(generation!==voiceGeneration)return;await v.capture?.cancel().catch(()=>{});v.capture=null;v.status='idle';v.error=error.name==='NotAllowedError'?'麦克风许可被拒绝。没有发送音频。请在浏览器站点设置中检查权限。':error.name==='NotFoundError'?'未找到可用麦克风。':error.message;renderVoice();}}
async function stopVoice(){const v=voiceSession;if(!v?.capture||!['recording','requesting'].includes(v.status))return;const generation=voiceGeneration;v.status='stopping';renderVoice();try{const blob=await v.capture.stop();if(generation!==voiceGeneration)return;v.capture=null;if(blob.size>v.cap.capture.maximumBytes)throw new Error('录音超过供应商大小限制，请缩短录音');v.blob=blob;v.status='captured';renderVoice()}catch(error){if(generation!==voiceGeneration)return;v.capture=null;v.blob=null;v.status='idle';v.error=error.message;renderVoice();}}
async function transcribeVoice(){const v=voiceSession;if(!v?.blob||v.status!=='captured')return;const generation=voiceGeneration;const audio=v.blob;v.blob=null;v.controller=new AbortController();v.status='transcribing';renderVoice();try{const response=await appFetch('/api/voice/transcribe',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'audio/wav','x-opendots-csrf':state.csrfToken||'','x-opendots-voice-consent':'transcribe'},body:audio,signal:v.controller.signal});const data=await response.json();if(!response.ok)throw new Error(data.error?.message||data.error||'转写请求未成功');if(generation!==voiceGeneration)return;if(typeof data.text!=='string'||data.sentToChat!==false)throw new Error('转写响应不符合预览协议');v.text=data.text;v.status='review';v.controller=null;renderVoice()}catch(error){if(generation!==voiceGeneration)return;v.controller=null;v.status='idle';v.error=error.name==='AbortError'?'转写已取消；请求可能已到达供应商。':'转写未确认：'+error.message+'。本页录音副本已丢弃，不会自动重试；重新录音会发起新请求。';renderVoice();}}
async function sendVoiceTranscript(){const v=voiceSession;if(!v||v.status!=='review'||busy)return;const text=v.attempt?.text||$('voice-transcript').value.trim();if(!text)return;if(!v.attempt&&text.length>4000){v.text=text;v.error='转写超过 4000 字符，请在发送前缩短内容。不会自动截断，也未生成提交编号。';renderVoice();return;}const old=(state.commands||[]).find(c=>c.kind==='chat'&&['pending','submitting','unknown'].includes(c.status)&&c.payload?.text===text&&!c.payload?.uploadIds);v.attempt=v.attempt||{text,key:old?.key||crypto.randomUUID()};v.text=text;busy=true;renderVoice();try{await request('/api/chat','POST',{text:v.attempt.text,idempotencyKey:v.attempt.key});if(voiceSession===v){closeModal();navigate('chat');}toast('转写文字已提交；等待助理真实回复')}catch(error){v.error=error.message;renderVoice()}finally{busy=false;if(voiceSession===v)renderVoice();await loadState()}}
async function readAloud(){const v=voiceSession;if(!v||v.kind!=='read'||v.status!=='idle'||!v.cap.operations?.readAloud)return;const generation=voiceGeneration;v.status='loading';v.controller=new AbortController();renderVoice();try{const response=await appFetch('/api/voice/read-aloud',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','x-opendots-csrf':state.csrfToken||''},body:JSON.stringify({messageId:v.messageId,consent:true}),signal:v.controller.signal});if(!response.ok){let data={};try{data=await response.json()}catch{}throw new Error(data.error?.message||data.error||'朗读请求失败')}const blob=await response.blob();if(blob.size>v.cap.readAloud.maximumBytes||!blob.type.startsWith('audio/'))throw new Error('返回音频格式或大小无效');if(generation!==voiceGeneration)return;v.audioUrl=URL.createObjectURL(blob);v.status='playing';v.controller=null;renderVoice();v.audio=$('voice-playback');v.audio.src=v.audioUrl;await v.audio.play().catch(()=>{v.error='浏览器未自动播放，请使用音频控件。';toast(v.error)})}catch(error){if(generation!==voiceGeneration)return;v.controller=null;v.status='idle';v.error=error.message+'；不会自动重试。';renderVoice()}}
function voiceAction(action){if(action==='stream-start')startStreamVoice();else if(action==='stream-stop')finishStreamVoice();else if(action==='stream-choice')selectStreamingVoice();else if(action==='record')recordVoice();else if(action==='stop')stopVoice();else if(action==='transcribe')transcribeVoice();else if(action==='send')sendVoiceTranscript();else if(action==='read')readAloud();}
document.addEventListener('visibilitychange',()=>{if(document.hidden&&voiceSession?.kind==='stream'){closeModal();}});window.addEventListener('pagehide',()=>{void cleanupVoice()});
let notificationView=null,notificationModalGeneration=null;
async function openNotifications(){const modalToken=++modalGeneration;void cleanupVoice();try{const data=await request('/api/notifications');if(modalToken!==modalGeneration)return;notificationView=data;renderNotifications(true,modalToken)}catch(error){toast(error.message)}}
function renderNotifications(open=false,expectedGeneration){if(!open&&(notificationModalGeneration!==modalGeneration||voiceSession))return;const data=notificationView;if(!data)return;const html=`<div class="section-head"><h2>应用内通知</h2><button data-action="close-modal" aria-label="关闭通知">×</button></div><p class="small muted">仅保存在这个应用内，不发送外部消息或系统推送，不请求通知权限。</p><div class="section-head"><span class="tag">${data.mode==='off'?'提醒已关闭':escapeHtml(data.unread||0)+' 条未读'}</span><button data-notification-mode="${data.mode==='off'?'all':'off'}">${data.mode==='off'?'开启应用内提醒':'关闭应用内提醒'}</button></div>${data.mode==='off'?'<p class="small muted">关闭后，尚未投递和后续重放的提醒不会继续出现。</p>':''}<div class="notifications-list">${data.items?.length?data.items.map(n=>`<article class="panel panel-pad ${n.read?'notification-read':''}"><div class="small"><strong>${escapeHtml(n.title)}</strong>${n.read?'':' <span class="tag">未读</span>'}</div><p class="small muted">${escapeHtml(n.reason||'')}</p><div class="small muted">${escapeHtml(formatTime(n.createdAt))} · ${escapeHtml(statusName(n.sourceStatus))}</div><button data-notification="${escapeHtml(n.id)}">查看${n.target==='approvals'?'待审批操作':n.target==='tasks'?'任务':'对话'} →</button></article>`).join(''):empty('这里暂时很安静','需要你确认的操作和已结束的任务，会按设置显示。')}</div><div class="modal-actions">${data.nextCursor?'<button data-action="more-notifications">加载更多</button>':''}<button data-action="ack-visible-notifications" ${!data.items?.some(n=>!n.read)?'disabled':''}>将当前列表标为已读</button></div>`;if(open){if(openModal(html,{expectedGeneration}))notificationModalGeneration=modalGeneration;}else $('modal').innerHTML=html;}
async function ackNotification(id){const notice=notificationView?.items?.find(n=>n.id===id);if(!notice)return;try{await request('/api/notifications/ack','POST',{ids:[id]});closeModal();navigate(notice.target==='conversation'?'chat':'tasks');await loadState()}catch(error){toast(error.message)}}
async function notificationAction(action,value){try{if(action==='mode'){await request('/api/notifications/mode','POST',{mode:value});notificationView=await request('/api/notifications');}else if(action==='ack'){const ids=(notificationView?.items||[]).filter(n=>!n.read).map(n=>n.id);if(!ids.length)return;await request('/api/notifications/ack','POST',{ids});notificationView=await request('/api/notifications');}else if(action==='more'&&notificationView?.nextCursor){const page=await request('/api/notifications/page','POST',{limit:30,after:notificationView.nextCursor});const prior=notificationView.items||[];notificationView={...page,items:[...prior,...(page.items||[]).filter(n=>!prior.some(p=>p.id===n.id))]};}renderNotifications();await loadState()}catch(error){toast(error.message)}}
async function loadSettings(){void loadOwnerSessions();void loadConnectors();try{settingsData=await request('/api/models');renderModelSettings()}catch(error){if(view==='settings'&&$('model-settings'))$('model-settings').innerHTML='<div class="tag amber">配置接口未就绪</div><p class="small muted">'+escapeHtml(error.message)+'</p><p class="small muted">请检查 Morphz 运行时配置。这里不会暂存密钥或显示虚假的连接成功。</p>';}}
function renderModelSettings(){if(!$('model-settings'))return;const data=settingsData;const options=data.catalog?.options||[];const accounts=data.accounts||[];$('model-settings').innerHTML=`<span class="tag">${data.catalog?.current?'当前模型：'+escapeHtml(data.catalog.current):'还没有选择模型'}</span><p class="runtime-note">此设置会更改整个 Runtime 的默认模型，也影响继承默认值的其他会话。建议为 opendots 使用专用 Runtime。版本检查仅是本产品的乐观检查，不是上游原子锁。</p><form id="model-select-form"><label class="form-field">模型<select name="model" required>${options.map(o=>`<option value="${escapeHtml(o.id)}" ${o.id===data.catalog?.current?'selected':''}>${escapeHtml(o.label||o.id)}</option>`).join('')}</select></label><button class="primary" ${!options.length?'disabled':''}>设为当前模型</button></form><h4 data-layout="l9">可用账户</h4>${accounts.length?accounts.map(a=>`<div data-layout="l10"><div class="small"><strong>${escapeHtml(a.label)}</strong> <span class="tag">${escapeHtml(a.state)}</span></div><div class="small muted">${escapeHtml(a.kind)} · ${escapeHtml((a.models||[]).join('、')||'未列出模型')}</div><button data-layout="l11" data-account="${escapeHtml(a.id)}" ${(data.binding?.accountIds||[]).includes(a.id)?'disabled':''}>${(data.binding?.accountIds||[]).includes(a.id)?'已绑定':'绑定到当前助理'}</button></div>`).join(''):'<p class="small muted">还没有已配置账户。</p>'}<details data-layout="l6"><summary data-layout="l12">＋ 连接自己的 API 账户</summary><p class="small muted">由你输入密钥，保存到 Morphz Secret Store。不会自动进行收费推理测试。</p><form id="model-connect-form" autocomplete="off"><label class="form-field">账户名称<input name="label" required maxlength="100" placeholder="我的模型账户"></label><label class="form-field">协议<select name="protocol"><option value="openai-responses">OpenAI Responses</option><option value="openai-chat">OpenAI-compatible Chat</option><option value="anthropic-messages">Anthropic Messages</option><option value="gemini-content">Gemini Content</option></select></label><label class="form-field">Base URL<input name="baseUrl" type="url" required placeholder="https://你的模型服务地址" autocomplete="off"></label><label class="form-field">模型 ID<input name="model" required placeholder="供应商提供的模型标识" autocomplete="off"></label><label class="form-field">API Key<input name="apiKey" type="password" required autocomplete="new-password" spellcheck="false" aria-describedby="key-note"></label><p id="key-note" class="small muted">密钥不会被写入浏览器存储、聊天或前端日志。提交后清空输入。</p><button class="primary">保存账户配置 / 重试原请求</button><button type="button" data-action="abandon-model">放弃原请求标识</button><p class="small muted">未确认时，只保存请求编号和非敏感配置指纹以便刷新后重试；不保存密钥或其哈希。重试前请先检查已有账户。</p><div id="model-error" class="inline-error" role="alert"></div></form></details><p class="small muted" data-layout="l13">${data.probePerformed?'服务端已返回检测结果。':'尚未执行推理测试；已配置不代表实际调用已验证。'}</p>`;}
async function modelMutation(path,body){if(busy)return;busy=true;try{await request(path,'POST',body);toast('配置已保存；尚未执行收费推理测试');await loadSettings();await loadState();}catch(error){toast(error.message)}finally{busy=false}}
function modelFingerprint(config){return JSON.stringify([config.label,config.protocol,config.baseUrl,config.model]);}
function modelAttemptKey(){return 'opendots:model-attempt:'+String(state.binding?.sessionId||'unbound');}
function readModelAttempt(){try{return JSON.parse(sessionStorage.getItem(modelAttemptKey())||'null')}catch{return null}}
function clearModelAttempt(){try{sessionStorage.removeItem(modelAttemptKey())}catch{}}
function prepareModelAttempt(config){const url=new URL(config.baseUrl);if(url.username||url.password||url.search||url.hash)throw new Error('Base URL 不得包含凭据、查询参数或片段；请把密钥仅填入 API Key 字段。');const fingerprint=modelFingerprint(config);const old=readModelAttempt();if(old&&old.fingerprint!==fingerprint)throw new Error('存在未确认的模型配置请求。请先检查账户列表，或明确放弃原请求再更改配置。');const attempt=old||{requestId:crypto.randomUUID(),fingerprint};try{sessionStorage.setItem(modelAttemptKey(),JSON.stringify(attempt))}catch{throw new Error('浏览器无法保存非敏感重试标识，请先允许此站点会话存储。')}return attempt.requestId;}
async function connectModel(form){if(busy)return;const fields=new FormData(form);const payload={requestId:'',label:String(fields.get('label')||''),protocol:String(fields.get('protocol')||''),baseUrl:String(fields.get('baseUrl')||''),model:String(fields.get('model')||''),apiKey:String(fields.get('apiKey')||'')};form.elements.apiKey.value='';try{payload.requestId=prepareModelAttempt(payload)}catch(error){payload.apiKey='';toast(error.message);return}busy=true;for(const b of form.querySelectorAll('button'))b.disabled=true;try{await request('/api/models/connect','POST',payload);clearModelAttempt();toast('账户已保存。请在列表中明确绑定账户并选择模型。');await loadSettings()}catch(error){const errorEl=$('model-error');if(errorEl)errorEl.textContent=error.message;else toast(error.message)}finally{payload.apiKey='';busy=false;for(const b of form.querySelectorAll('button'))b.disabled=false}}
document.addEventListener('click',event=>{if(event.target.id==='attachment-input')filePickerOpen=true;const b=event.target.closest('button');if(!b||b.disabled)return;if(b.dataset.artifactDocument)openArtifactDocument(b.dataset.artifactDocument);else if(b.dataset.registerArtifact)openArtifactEditor('create',b.dataset.registerArtifact);else if(b.dataset.artifactDocuments)artifactDocumentAction(b.dataset.artifactDocuments);else if(b.dataset.proposalId)openProposal(b.dataset.proposalId);else if(b.dataset.proposalAction)proposalAction(b.dataset.proposalAction);else if(b.dataset.proposals){if(b.dataset.proposals==='open-list')navigate('tasks');else loadProposals(b.dataset.proposals==='more');}else if(b.dataset.calendarHistory)calendarHistory(b.dataset.calendarHistory);else if(b.dataset.calendarControl)controlCalendar(b.dataset.calendarId,b.dataset.calendarControl);else if(b.dataset.calendar)calendarAction(b.dataset.calendar);else if(b.dataset.connectors)loadConnectors(b.dataset.connectors==='native');else if(b.dataset.ownerDevice)openOwnerSessionAction('revoke',b.dataset.ownerDevice);else if(b.dataset.ownerSession){if(b.dataset.ownerSession==='refresh')loadOwnerSessions();else openOwnerSessionAction(b.dataset.ownerSession);}else if(b.dataset.computerApproval)openComputerApproval(b.dataset.computerApproval);else if(b.dataset.computerDecision)decideComputerApproval(b.dataset.computerDecision);else if(b.dataset.action==='computer-approvals')openComputerApprovals();else if(b.dataset.jobInput)openTaskInput(b.dataset.jobInput);else if(b.dataset.action==='refresh-task-input')refreshTaskInput();else if(b.dataset.action==='unlock-rejected-attachments')unlockRejectedAttachmentDraft();else if(b.dataset.action==='stop-upload-transfer'){uploadStopRequested=true;uploadController?.abort();toast('正在停止传输；原暂存不会自动删除。');}else if(b.dataset.upload)uploadAttachment(b.dataset.upload);else if(b.dataset.resumeUpload)uploadAttachment(b.dataset.resumeUpload);else if(b.dataset.cancelUpload)cancelAttachment(b.dataset.cancelUpload);else if(b.dataset.action==='restore-upload-draft')restoreStagedDraft();else if(b.dataset.voice)voiceAction(b.dataset.voice);else if(b.dataset.readAloud)openReadAloud(b.dataset.readAloud);else if(b.dataset.notification)ackNotification(b.dataset.notification);else if(b.dataset.notificationMode)notificationAction('mode',b.dataset.notificationMode);else if(b.dataset.action==='notifications')openNotifications();else if(b.dataset.action==='more-notifications')notificationAction('more');else if(b.dataset.action==='ack-visible-notifications')notificationAction('ack');else if(b.dataset.action==='refresh-artifacts')loadArtifacts();else if(b.dataset.memory)readMemory(b.dataset.memory);else if(b.dataset.reminder)controlReminder(b.dataset.reminder,b.dataset.control);else if(b.dataset.action==='refresh-reminders')loadReminders();else if(b.dataset.computer)computerAction(b.dataset.computer);else if(b.dataset.retryCommand){const c=(state.commands||[]).find(c=>c.id===b.dataset.retryCommand);if(c){if(!c.payload?.uploadIds&&activeAttachments().length){toast('请先处理当前附件草稿，再恢复不含附件的原请求。');return}restoreAttachmentCommand(c);draft=String(c.payload?.text||c.payload?.prompt||'');pendingSubmission={text:draft,endpoint:c.kind==='objective'?'/api/jobs':'/api/chat',key:c.key};navigate('chat');$('background-task').checked=c.kind==='objective';}}else if(b.dataset.action==='abandon-model'){if(window.confirm('先检查账户列表。放弃未确认请求可能导致重复账户，仍要开始新的配置尝试吗？')){clearModelAttempt();toast('已放弃本地重试标识，请确认原请求结果后再提交');}}else if(b.dataset.account)modelMutation('/api/models/account',{accountId:b.dataset.account});else if(b.dataset.view)navigate(b.dataset.view);else if(b.dataset.approval)openApproval(b.dataset.approval);else if(b.dataset.decision)decideApproval(b.dataset.decision);else if(b.dataset.job)controlJob(b.dataset.job,b.dataset.control);else if(b.dataset.action==='refresh')loadState(true);else if(b.dataset.action==='close-modal')closeModal();else if(b.dataset.action==='voice')openVoice()});
document.addEventListener('submit',e=>{if(e.target.id==='chat-form')sendMessage(e);else if(e.target.id==='task-input-form'){e.preventDefault();submitTaskInput()}else if(e.target.id==='memory-search-form'){e.preventDefault();searchMemory(e.target)}else if(e.target.id==='artifact-version-form'){e.preventDefault();previewArtifactVersion(e.target)}else if(e.target.id==='calendar-form'){e.preventDefault();previewCalendar(e.target)}else if(e.target.id==='reminder-form'){e.preventDefault();createReminder(e.target)}else if(e.target.id==='model-connect-form'){e.preventDefault();connectModel(e.target)}else if(e.target.id==='model-select-form'){e.preventDefault();modelMutation('/api/models/select',{model:e.target.elements.model.value,expectedCurrent:settingsData?.catalog?.current??null})}});
document.addEventListener('change',event=>{if(event.target.id==='attachment-input'){filePickerOpen=false;const files=Array.from(event.target.files||[]);event.target.value='';event.target.multiple=true;if(files.length)chooseAttachments(files)}});
document.addEventListener('cancel',event=>{if(event.target.id==='attachment-input'){filePickerOpen=false;attachmentResumeKey=null;}});
document.addEventListener('input',e=>{if(e.target.id==='message-input')draft=e.target.value});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)&&e.target.id==='message-input')e.target.form.requestSubmit();if(e.key==='Tab'&&!$('modalback').hidden){const items=[...$('modal').querySelectorAll('button:not(:disabled),input,select,textarea,a[href]')];if(!items.length){e.preventDefault();return}if(e.shiftKey&&(document.activeElement===items[0]||document.activeElement===$('modal'))){e.preventDefault();items.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===items.at(-1)){e.preventDefault();items[0].focus()}}});
$('modalback').addEventListener('click',e=>{if(e.target===$('modalback')&&!busy)closeModal()});
window.addEventListener('popstate',()=>navigate(location.hash?.slice(1)||'chat',false));
render();loadState(true).then(()=>{void loadAttachments();void voiceCapabilities().then(()=>{if(view==='chat'&&$('modalback').hidden)render()}).catch(()=>{});if(view==='settings')loadSettings();if(view==='computer')loadComputer();if(view==='tasks'){loadReminders();loadCalendars();loadProposals();}if(view==='files')loadArtifacts()});setInterval(()=>{if(!document.hidden)loadState()},2500);
setInterval(()=>{if(document.hidden||busy)return;if(view==='computer')loadComputer();if(view==='tasks')loadReminders()},10000);
